api.look('agent');
const cx=api.w/2, cy=330;
const k=api.seg(t,0,1.2);
api.circle(cx,cy-110,28,{c:'accent',w:5,k,fill:'accent'});
api.line(cx,cy-80,cx,cy+30,{c:'fg',w:6,k:api.seg(t,0.3,1)});
api.line(cx,cy-60,cx-70,cy-20,{c:'fg',w:6,k:api.seg(t,0.5,1.2)});
api.line(cx,cy-60,cx+70,cy-20,{c:'fg',w:6,k:api.seg(t,0.5,1.2)});
api.line(cx,cy+30,cx-45,cy+120,{c:'fg',w:6,k:api.seg(t,0.7,1.4)});
api.line(cx,cy+30,cx+45,cy+120,{c:'fg',w:6,k:api.seg(t,0.7,1.4)});
api.kinetic('20 MIN',cx,cy+210,{mode:'pop',k:api.seg(t,1,2),size:44,hot:'accent',t});
api.say('Twenty minutes, no equipment',0.2,3.3);

api.look('agent');
const cx=api.w/2, cy=330, T=Math.PI*2;
const names=['Squat','Push-up','Lunge','Plank'];
const idx=Math.min(3,Math.floor(t/1.5));
const p=Math.sin((t%1.5)/1.5*Math.PI);
const hx=cx, hy=cy-110+p*[60,50,40,30][idx];
const col=['accent','a2','a3','good'][idx];
api.circle(hx,hy,28,{c:col,w:5,fill:col});
const sy=hy+30, hipy=sy+110+p*[20,0,20,0][idx];
api.line(hx,sy,hx,hipy,{c:'fg',w:7});
const arm=[[-60,20-p*40],[-80,60],[-60,60-p*30],[-80,60]][idx];
api.line(hx,sy+15,hx+arm[0],sy+arm[1]+15,{c:'fg',w:7});
api.line(hx,sy+15,hx-arm[0],sy+arm[1]+15,{c:'fg',w:7});
const kn=40+p*[30,0,40,0][idx];
api.line(hx,hipy,hx-kn,hipy+60,{c:'fg',w:7});
api.line(hx-kn,hipy+60,hx-kn+(idx==2?-30:0),hipy+130-p*20,{c:'fg',w:7});
api.line(hx,hipy,hx+kn,hipy+60,{c:'fg',w:7});
api.line(hx+kn,hipy+60,hx+kn,hipy+130-p*20,{c:'fg',w:7});
api.line(cx-120,hipy+135,cx+120,hipy+135,{c:'dim',w:3});
api.kinetic(names[idx],cx,cy-200,{mode:'pop',k:api.seg(t%1.5,0,0.4),size:40,hot:col,t:t%1.5});
for(let i=0;i<4;i++)api.dot(cx-45+i*30,hipy+190,i==idx?9:5,{c:i==idx?col:'dim'});
api.say('Squats, push-ups, lunges, planks',0.3,5.7);

api.look('agent');
const cx=api.w/2, cy=340;
const cyc=(t%2)/2;
api.donut([{v:40,c:'accent'},{v:20,c:'a2'}],cx,cy,120,{k:api.seg(t,0,1)});
api.counter(40,cx,cy+10,{k:api.seg(t,0.3,1.5),suf:'s',size:60,d:0});
api.text('ON',cx,cy-45,{size:22,c:'accent',align:'center'});
api.text('then 20s rest',cx,cy+70,{size:20,c:'a2',align:'center',k:api.seg(t,1.5,2.5)});
const a=-Math.PI/2+cyc*Math.PI*2;
api.dot(cx+Math.cos(a)*150,cy+Math.sin(a)*150,10,{c:'fg'});
api.swarm(30,t,{mode:'orbit',cx,cy,rx:170,ry:170,c:'a3'});
api.say('Forty on, twenty off',0.3,5.7);

api.look('agent');
const cx=api.w/2;
const items=[{label:'Warm up',v:4,c:'a2'},{label:'Circuit x3',v:12,c:'accent'},{label:'Cool down',v:4,c:'a3'}];
api.bars(items,40,200,api.w-80,300,{k:api.seg(t,0,2)});
api.timeline([{t:'0',s:'Start'},{t:'4',s:'Circuit'},{t:'16',s:'Cool'},{t:'20',s:'Done'}],40,580,api.w-80,{k:api.seg(t,1.5,3.5)});
api.kinetic('20 MIN',cx,130,{mode:'rise',k:api.seg(t,0,1),size:40,hot:'accent',t});
api.say('Four, twelve, four minutes',0.3,5.7);

api.look('agent');
const cx=api.w/2, cy=340;
api.shape('heart',cx,cy,200+api.pulse(t,1.5)*20,{c:'accent',fill:'accent',k:api.seg(t,0,1.2)});
api.shape('check',cx,cy,90,{c:'fg',w:8,k:api.seg(t,1,2)});
api.swarm(60,t,{mode:'burst',cx,cy,c:'a2',k:api.seg(t,1,2)});
api.kinetic('Done',cx,cy+210,{mode:'pop',k:api.seg(t,1.5,2.5),size:44,hot:'a2',t});
api.say('Twenty minutes, all you',0.3,4.7);
